                total_credit_cents += credit_cents
                total_amount_due_cents += amount_due_cents
            return {
                "release": release,
                "credit_cents": total_credit_cents,
                "amount_due_cents": total_amount_due_cents
            }
    return {"error": "unknown_command"}


